create extension if not exists pgcrypto;
create table if not exists public.perfis(user_id uuid primary key references auth.users(id) on delete cascade,nome text not null,referencia text,role text not null default 'user' check(role in('user','admin')),criado_em timestamptz not null default now());
create table if not exists public.links_compartilhados(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.perfis(user_id) on delete cascade,token text not null unique,slug text not null unique,ativo boolean not null default true,criado_em timestamptz not null default now(),atualizado_em timestamptz not null default now());
create table if not exists public.localizacoes(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.perfis(user_id) on delete cascade,link_id uuid not null references public.links_compartilhados(id) on delete cascade,latitude double precision not null,longitude double precision not null,precisao_metros double precision,endereco_formatado text,user_agent text,capturado_em timestamptz not null default now());
alter table public.perfis enable row level security; alter table public.links_compartilhados enable row level security; alter table public.localizacoes enable row level security;
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.perfis where user_id=auth.uid() and role='admin')$$;
drop policy if exists "perfil proprio" on public.perfis; create policy "perfil proprio" on public.perfis for select to authenticated using(user_id=auth.uid() or public.is_admin());
drop policy if exists "perfil cadastro" on public.perfis; create policy "perfil cadastro" on public.perfis for insert to authenticated with check(user_id=auth.uid() and role='user');
drop policy if exists "perfil update" on public.perfis; create policy "perfil update" on public.perfis for update to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
drop policy if exists "link proprio" on public.links_compartilhados; create policy "link proprio" on public.links_compartilhados for select to authenticated using(user_id=auth.uid() or public.is_admin());
drop policy if exists "link insert" on public.links_compartilhados; create policy "link insert" on public.links_compartilhados for insert to authenticated with check(user_id=auth.uid());
drop policy if exists "link update" on public.links_compartilhados; create policy "link update" on public.links_compartilhados for update to authenticated using(user_id=auth.uid() or public.is_admin()) with check(user_id=auth.uid() or public.is_admin());
drop policy if exists "link publico" on public.links_compartilhados; create policy "link publico" on public.links_compartilhados for select to anon using(ativo=true);
drop policy if exists "loc proprio" on public.localizacoes; create policy "loc proprio" on public.localizacoes for select to authenticated using(user_id=auth.uid() or public.is_admin());
drop policy if exists "loc publico insert" on public.localizacoes; create policy "loc publico insert" on public.localizacoes for insert to anon,authenticated with check(exists(select 1 from public.links_compartilhados l where l.id=link_id and l.user_id=user_id and l.ativo=true));
create or replace view public.admin_resumo as select p.user_id,p.nome,p.referencia,p.criado_em,u.email,case when exists(select 1 from public.links_compartilhados l where l.user_id=p.user_id and l.ativo) then 'ativo' else 'sem link ativo' end status,(select count(*) from public.localizacoes x where x.user_id=p.user_id) total_localizacoes from public.perfis p join auth.users u on u.id=p.user_id where public.is_admin();
grant usage on schema public to anon,authenticated; grant select,insert,update on public.perfis to authenticated; grant select,insert,update on public.links_compartilhados to authenticated; grant select,insert on public.localizacoes to anon,authenticated; grant select on public.admin_resumo to authenticated;
-- Depois de criar a conta do administrador: update public.perfis set role='admin' where user_id='UUID_DO_ADMIN';
